import backtrader as bt  # РРјРїРѕСЂС‚РёСЂСѓРµРј Backtrader, С‡С‚РѕР±С‹ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊ РµРіРѕ Р±Р°Р·РѕРІС‹Р№ РєР»Р°СЃСЃ СЃС‚СЂР°С‚РµРіРёРё Рё СѓС‚РёР»РёС‚С‹ РґР°С‚.


class BaseLoggingStrategy(bt.Strategy):  # РЎРѕР·РґР°РµРј Р±Р°Р·РѕРІС‹Р№ РєР»Р°СЃСЃ, РєРѕС‚РѕСЂС‹Р№ РѕС‚РІРµС‡Р°РµС‚ С‚РѕР»СЊРєРѕ Р·Р° СЃР±РѕСЂ Р»РѕРіРѕРІ СЃРґРµР»РѕРє Рё РєСЂРёРІРѕР№ РєР°РїРёС‚Р°Р»Р°.
    def __init__(self):  # РЎРѕР·РґР°РµРј РёРЅРёС†РёР°Р»РёР·Р°С†РёСЋ Р±Р°Р·РѕРІРѕР№ СЃС‚СЂР°С‚РµРіРёРё, С‡С‚РѕР±С‹ РїРѕРґРіРѕС‚РѕРІРёС‚СЊ СЃС‚СЂСѓРєС‚СѓСЂС‹ РґР»СЏ Р»РѕРіРёСЂРѕРІР°РЅРёСЏ.
        self.order = None  # РЎРѕР·РґР°РµРј РїРµСЂРµРјРµРЅРЅСѓСЋ РґР»СЏ С…СЂР°РЅРµРЅРёСЏ С‚РµРєСѓС‰РµРіРѕ Р±РёСЂР¶РµРІРѕРіРѕ РїСЂРёРєР°Р·Р°, С‡С‚РѕР±С‹ РґРѕС‡РµСЂРЅРёРµ СЃС‚СЂР°С‚РµРіРёРё РЅРµ РѕС‚РїСЂР°РІР»СЏР»Рё РґСѓР±Р»РёРєР°С‚С‹.
        self.trades_log = []  # РЎРѕР·РґР°РµРј СЃРїРёСЃРѕРє, РІ РєРѕС‚РѕСЂС‹Р№ Р±СѓРґРµРј СЃРєР»Р°РґС‹РІР°С‚СЊ РёРЅС„РѕСЂРјР°С†РёСЋ РїРѕ Р·Р°РєСЂС‹С‚С‹Рј СЃРґРµР»РєР°Рј.
        self.equity_curve = []  # РЎРѕР·РґР°РµРј СЃРїРёСЃРѕРє РґР»СЏ СЃРѕС…СЂР°РЅРµРЅРёСЏ РёСЃС‚РѕСЂРёРё РёР·РјРµРЅРµРЅРёСЏ РєР°РїРёС‚Р°Р»Р° РїРѕ СЃРІРµС‡Р°Рј.
        self.current_trade_entry = {}  # РЎРѕР·РґР°РµРј СЃР»РѕРІР°СЂСЊ РґР»СЏ РІСЂРµРјРµРЅРЅРѕРіРѕ С…СЂР°РЅРµРЅРёСЏ РґР°РЅРЅС‹С… РїРѕ С‚РµРєСѓС‰РµР№ РѕС‚РєСЂС‹С‚РѕР№ СЃРґРµР»РєРµ.
        self.current_trade_exit_price = None  # РЎРѕР·РґР°РµРј РїРµСЂРµРјРµРЅРЅСѓСЋ РґР»СЏ С…СЂР°РЅРµРЅРёСЏ С†РµРЅС‹ Р·Р°РєСЂС‹С‚РёСЏ РїРѕР·РёС†РёРё РїРµСЂРµРґ Р·Р°РїРёСЃСЊСЋ СЃРґРµР»РєРё РІ Р»РѕРі.
        self.current_trade_exit_date = None  # РЎРѕР·РґР°РµРј РїРµСЂРµРјРµРЅРЅСѓСЋ РґР»СЏ С…СЂР°РЅРµРЅРёСЏ РґР°С‚С‹ Р·Р°РєСЂС‹С‚РёСЏ РїРѕР·РёС†РёРё РїРµСЂРµРґ Р·Р°РїРёСЃСЊСЋ СЃРґРµР»РєРё РІ Р»РѕРі.
        self.final_portfolio_value = None  # Снимок финального капитала для корректной оптимизации.

    def record_equity(self):  # РЎРѕР·РґР°РµРј РІСЃРїРѕРјРѕРіР°С‚РµР»СЊРЅС‹Р№ РјРµС‚РѕРґ, РєРѕС‚РѕСЂС‹Р№ СЃРѕС…СЂР°РЅСЏРµС‚ С‚РµРєСѓС‰РёР№ РєР°РїРёС‚Р°Р» РЅР° РєР°Р¶РґРѕР№ СЃРІРµС‡Рµ.
        current_datetime = bt.num2date(self.data.datetime[0])  # РџРѕР»СѓС‡Р°РµРј РґР°С‚Сѓ Рё РІСЂРµРјСЏ С‚РµРєСѓС‰РµР№ СЃРІРµС‡Рё РёР· Backtrader.
        current_equity = self.broker.getvalue()  # РџРѕР»СѓС‡Р°РµРј С‚РµРєСѓС‰СѓСЋ СЃС‚РѕРёРјРѕСЃС‚СЊ СЃС‡РµС‚Р° СЃ СѓС‡РµС‚РѕРј РѕС‚РєСЂС‹С‚С‹С… РїРѕР·РёС†РёР№.
        self.equity_curve.append({"datetime": current_datetime, "equity": current_equity})  # Р”РѕР±Р°РІР»СЏРµРј РЅРѕРІСѓСЋ С‚РѕС‡РєСѓ РІ РёСЃС‚РѕСЂРёСЋ РєР°РїРёС‚Р°Р»Р°.

    def prenext(self):  # РЎРѕР·РґР°РµРј РјРµС‚РѕРґ, РєРѕС‚РѕСЂС‹Р№ Backtrader РІС‹Р·С‹РІР°РµС‚ РЅР° РїРµСЂРІС‹С… СЃРІРµС‡Р°С… РґРѕ РїРѕР»РЅРѕРіРѕ РїСЂРѕРіСЂРµРІР° РёРЅРґРёРєР°С‚РѕСЂРѕРІ.
        self.record_equity()  # РЎРѕС…СЂР°РЅСЏРµРј РєР°РїРёС‚Р°Р» РґР°Р¶Рµ РЅР° СЂР°РЅРЅРёС… СЃРІРµС‡Р°С…, С‡С‚РѕР±С‹ РіСЂР°С„РёРє РєР°РїРёС‚Р°Р»Р° Р±С‹Р» РЅРµРїСЂРµСЂС‹РІРЅС‹Рј.

    def stop(self):
        try:
            self.final_portfolio_value = float(self.broker.getvalue())
        except Exception:
            self.final_portfolio_value = None

    def notify_order(self, order):  # РЎРѕР·РґР°РµРј РјРµС‚РѕРґ, РєРѕС‚РѕСЂС‹Р№ Backtrader РІС‹Р·С‹РІР°РµС‚ РїСЂРё РёР·РјРµРЅРµРЅРёРё СЃРѕСЃС‚РѕСЏРЅРёСЏ РїСЂРёРєР°Р·Р°.
        if order.status in [order.Submitted, order.Accepted]:  # РџСЂРѕРІРµСЂСЏРµРј, Р±С‹Р» Р»Рё РїСЂРёРєР°Р· С‚РѕР»СЊРєРѕ РѕС‚РїСЂР°РІР»РµРЅ РёР»Рё РїСЂРёРЅСЏС‚ РІ РѕР±СЂР°Р±РѕС‚РєСѓ.
            return  # РќРёС‡РµРіРѕ РЅРµ РґРµР»Р°РµРј, РїРѕРєР° РїСЂРёРєР°Р· РµС‰Рµ РЅРµ РёСЃРїРѕР»РЅРµРЅ.
        if order.status == order.Completed:  # РџСЂРѕРІРµСЂСЏРµРј, Р±С‹Р» Р»Рё РїСЂРёРєР°Р· РёСЃРїРѕР»РЅРµРЅ РїРѕР»РЅРѕСЃС‚СЊСЋ.
            executed_datetime = bt.num2date(order.executed.dt)  # РџСЂРµРѕР±СЂР°Р·СѓРµРј РІСЂРµРјСЏ РёСЃРїРѕР»РЅРµРЅРёСЏ РїСЂРёРєР°Р·Р° РІ РѕР±С‹С‡РЅС‹Р№ С„РѕСЂРјР°С‚ РґР°С‚С‹ Рё РІСЂРµРјРµРЅРё.
            if order.isbuy():  # РџСЂРѕРІРµСЂСЏРµРј, С‡С‚Рѕ РёСЃРїРѕР»РЅРµРЅРЅС‹Р№ РїСЂРёРєР°Р· СЏРІР»СЏРµС‚СЃСЏ РїРѕРєСѓРїРєРѕР№.
                self.current_trade_entry = {  # РЎРѕС…СЂР°РЅСЏРµРј РѕСЃРЅРѕРІРЅС‹Рµ РїР°СЂР°РјРµС‚СЂС‹ РѕС‚РєСЂС‹С‚РѕР№ РїРѕР·РёС†РёРё РІРѕ РІСЂРµРјРµРЅРЅС‹Р№ СЃР»РѕРІР°СЂСЊ.
                    "open_date": executed_datetime,  # Р—Р°РїРѕРјРёРЅР°РµРј РґР°С‚Сѓ РѕС‚РєСЂС‹С‚РёСЏ СЃРґРµР»РєРё.
                    "open_price": order.executed.price,  # Р—Р°РїРѕРјРёРЅР°РµРј С„Р°РєС‚РёС‡РµСЃРєСѓСЋ С†РµРЅСѓ РѕС‚РєСЂС‹С‚РёСЏ СЃРґРµР»РєРё.
                    "size": order.executed.size,  # Р—Р°РїРѕРјРёРЅР°РµРј СЂР°Р·РјРµСЂ РєСѓРїР»РµРЅРЅРѕР№ РїРѕР·РёС†РёРё.
                }  # Р—Р°РІРµСЂС€Р°РµРј Р·Р°РїРѕР»РЅРµРЅРёРµ СЃР»РѕРІР°СЂСЏ РїРѕ РѕС‚РєСЂС‹С‚РѕР№ СЃРґРµР»РєРµ.
            elif order.issell():  # РџСЂРѕРІРµСЂСЏРµРј, С‡С‚Рѕ РёСЃРїРѕР»РЅРµРЅРЅС‹Р№ РїСЂРёРєР°Р· СЏРІР»СЏРµС‚СЃСЏ РїСЂРѕРґР°Р¶РµР№ РёР»Рё Р·Р°РєСЂС‹С‚РёРµРј РїРѕР·РёС†РёРё.
                self.current_trade_exit_price = order.executed.price  # РЎРѕС…СЂР°РЅСЏРµРј С„Р°РєС‚РёС‡РµСЃРєСѓСЋ С†РµРЅСѓ Р·Р°РєСЂС‹С‚РёСЏ РїРѕР·РёС†РёРё.
                self.current_trade_exit_date = executed_datetime  # РЎРѕС…СЂР°РЅСЏРµРј РґР°С‚Сѓ Рё РІСЂРµРјСЏ Р·Р°РєСЂС‹С‚РёСЏ РїРѕР·РёС†РёРё.
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:  # РџСЂРѕРІРµСЂСЏРµРј, Р·Р°РІРµСЂС€РёР»СЃСЏ Р»Рё Р¶РёР·РЅРµРЅРЅС‹Р№ С†РёРєР» РїСЂРёРєР°Р·Р°.
            self.order = None  # РћС‡РёС‰Р°РµРј СЃСЃС‹Р»РєСѓ РЅР° РїСЂРёРєР°Р·, С‡С‚РѕР±С‹ СЃС‚СЂР°С‚РµРіРёСЏ РјРѕРіР»Р° РѕС‚РїСЂР°РІР»СЏС‚СЊ СЃР»РµРґСѓСЋС‰РёР№.

    def notify_trade(self, trade):  # РЎРѕР·РґР°РµРј РјРµС‚РѕРґ, РєРѕС‚РѕСЂС‹Р№ Backtrader РІС‹Р·С‹РІР°РµС‚ РїСЂРё РёР·РјРµРЅРµРЅРёРё СЃРѕСЃС‚РѕСЏРЅРёСЏ СЃРґРµР»РєРё.
        if not trade.isclosed:  # РџСЂРѕРІРµСЂСЏРµРј, Р·Р°РєСЂС‹Р»Р°СЃСЊ Р»Рё СЃРґРµР»РєР° РїРѕР»РЅРѕСЃС‚СЊСЋ.
            return  # Р•СЃР»Рё СЃРґРµР»РєР° РµС‰Рµ РѕС‚РєСЂС‹С‚Р°, РЅРёС‡РµРіРѕ РЅРµ Р·Р°РїРёСЃС‹РІР°РµРј РІ Р»РѕРі.
        open_date = self.current_trade_entry.get("open_date", bt.num2date(trade.dtopen))  # Р‘РµСЂРµРј РґР°С‚Сѓ РѕС‚РєСЂС‹С‚РёСЏ РёР· СЃРѕС…СЂР°РЅРµРЅРЅРѕРіРѕ СЃР»РѕРІР°СЂСЏ РёР»Рё Р·Р°РїР°СЃРЅРѕР№ РІР°СЂРёР°РЅС‚ РёР· РѕР±СЉРµРєС‚Р° СЃРґРµР»РєРё.
        open_price = self.current_trade_entry.get("open_price", trade.price)  # Р‘РµСЂРµРј С†РµРЅСѓ РѕС‚РєСЂС‹С‚РёСЏ РёР· СЃРѕС…СЂР°РЅРµРЅРЅРѕРіРѕ СЃР»РѕРІР°СЂСЏ РёР»Рё РёР· РѕР±СЉРµРєС‚Р° СЃРґРµР»РєРё.
        size = self.current_trade_entry.get("size", trade.size)  # Р‘РµСЂРµРј СЂР°Р·РјРµСЂ РїРѕР·РёС†РёРё РёР· СЃРѕС…СЂР°РЅРµРЅРЅРѕРіРѕ СЃР»РѕРІР°СЂСЏ РёР»Рё РёР· РѕР±СЉРµРєС‚Р° СЃРґРµР»РєРё.
        close_date = self.current_trade_exit_date or bt.num2date(trade.dtclose)  # Р‘РµСЂРµРј РґР°С‚Сѓ Р·Р°РєСЂС‹С‚РёСЏ РёР· РёСЃРїРѕР»РЅРµРЅРЅРѕРіРѕ РѕСЂРґРµСЂР° РёР»Рё Р·Р°РїР°СЃРЅРѕР№ РІР°СЂРёР°РЅС‚ РёР· РѕР±СЉРµРєС‚Р° СЃРґРµР»РєРё.
        close_price = self.current_trade_exit_price if self.current_trade_exit_price is not None else self.data.close[0]  # Р‘РµСЂРµРј С†РµРЅСѓ Р·Р°РєСЂС‹С‚РёСЏ РёР· СЃРѕС…СЂР°РЅРµРЅРЅРѕРіРѕ РѕСЂРґРµСЂР° РёР»Рё С‚РµРєСѓС‰РµР№ С†РµРЅС‹ Р·Р°РєСЂС‹С‚РёСЏ СЃРІРµС‡Рё.
        trade_record = {  # РЎРѕР·РґР°РµРј СЃР»РѕРІР°СЂСЊ СЃ РёС‚РѕРіРѕРІРѕР№ РёРЅС„РѕСЂРјР°С†РёРµР№ РїРѕ Р·Р°РєСЂС‹С‚РѕР№ СЃРґРµР»РєРµ.
            "open_date": open_date,  # РЎРѕС…СЂР°РЅСЏРµРј РґР°С‚Сѓ РѕС‚РєСЂС‹С‚РёСЏ СЃРґРµР»РєРё.
            "close_date": close_date,  # РЎРѕС…СЂР°РЅСЏРµРј РґР°С‚Сѓ Р·Р°РєСЂС‹С‚РёСЏ СЃРґРµР»РєРё.
            "open_price": float(open_price),  # РЎРѕС…СЂР°РЅСЏРµРј С†РµРЅСѓ РѕС‚РєСЂС‹С‚РёСЏ РєР°Рє С‡РёСЃР»Рѕ СЃ РїР»Р°РІР°СЋС‰РµР№ С‚РѕС‡РєРѕР№.
            "close_price": float(close_price),  # РЎРѕС…СЂР°РЅСЏРµРј С†РµРЅСѓ Р·Р°РєСЂС‹С‚РёСЏ РєР°Рє С‡РёСЃР»Рѕ СЃ РїР»Р°РІР°СЋС‰РµР№ С‚РѕС‡РєРѕР№.
            "size": float(abs(size)),  # РЎРѕС…СЂР°РЅСЏРµРј Р°Р±СЃРѕР»СЋС‚РЅС‹Р№ СЂР°Р·РјРµСЂ РїРѕР·РёС†РёРё, С‡С‚РѕР±С‹ РѕРЅ Р±С‹Р» СѓРґРѕР±РµРЅ РґР»СЏ С‡С‚РµРЅРёСЏ.
            "pnl": float(trade.pnl),  # РЎРѕС…СЂР°РЅСЏРµРј СЂРµР·СѓР»СЊС‚Р°С‚ СЃРґРµР»РєРё Р±РµР· СѓС‡РµС‚Р° РєРѕРјРёСЃСЃРёРё.
            "commission": float(trade.commission),  # РЎРѕС…СЂР°РЅСЏРµРј РѕР±С‰СѓСЋ РєРѕРјРёСЃСЃРёСЋ РїРѕ СЃРґРµР»РєРµ.
            "pnl_after_commission": float(trade.pnlcomm),  # РЎРѕС…СЂР°РЅСЏРµРј РёС‚РѕРіРѕРІС‹Р№ СЂРµР·СѓР»СЊС‚Р°С‚ СЃРґРµР»РєРё СѓР¶Рµ СЃ СѓС‡РµС‚РѕРј РєРѕРјРёСЃСЃРёРё.
        }  # Р—Р°РІРµСЂС€Р°РµРј С„РѕСЂРјРёСЂРѕРІР°РЅРёРµ СЃР»РѕРІР°СЂСЏ РїРѕ Р·Р°РєСЂС‹С‚РѕР№ СЃРґРµР»РєРµ.
        self.trades_log.append(trade_record)  # Р”РѕР±Р°РІР»СЏРµРј Р·Р°РєСЂС‹С‚СѓСЋ СЃРґРµР»РєСѓ РІ РѕР±С‰РёР№ СЃРїРёСЃРѕРє Р»РѕРіР°.
        self.current_trade_entry = {}  # РћС‡РёС‰Р°РµРј РІСЂРµРјРµРЅРЅС‹Рµ РґР°РЅРЅС‹Рµ РїРѕ РѕС‚РєСЂС‹С‚РѕР№ СЃРґРµР»РєРµ РїРѕСЃР»Рµ Р·Р°РїРёСЃРё РІ Р»РѕРі.
        self.current_trade_exit_price = None  # РћС‡РёС‰Р°РµРј СЃРѕС…СЂР°РЅРµРЅРЅСѓСЋ С†РµРЅСѓ Р·Р°РєСЂС‹С‚РёСЏ, С‡С‚РѕР±С‹ РѕРЅР° РЅРµ РїРѕРїР°Р»Р° РІ СЃР»РµРґСѓСЋС‰СѓСЋ СЃРґРµР»РєСѓ.
        self.current_trade_exit_date = None  # РћС‡РёС‰Р°РµРј СЃРѕС…СЂР°РЅРµРЅРЅСѓСЋ РґР°С‚Сѓ Р·Р°РєСЂС‹С‚РёСЏ, С‡С‚РѕР±С‹ РѕРЅР° РЅРµ РїРѕРїР°Р»Р° РІ СЃР»РµРґСѓСЋС‰СѓСЋ СЃРґРµР»РєСѓ.
